<?php
require_once __DIR__ . '/../includes/init.php';requireLogin();$search=trim((string)($_GET['q']??''));$category=trim((string)($_GET['category']??''));$sql='SELECT * FROM items WHERE 1=1';$params=[];if($search!==''){$sql.=' AND (item_code LIKE :q1 OR item_name LIKE :q2 OR location LIKE :q3)';$params['q1']="%$search%";$params['q2']="%$search%";$params['q3']="%$search%";}if($category!==''){$sql.=' AND category=:category';$params['category']=$category;}$sql.=' ORDER BY item_name';$s=db()->prepare($sql);$s->execute($params);$rows=$s->fetchAll();$categories=itemCategories();$title='Items';$active='items';layoutStart($title,$active);
?><div class="page-heading"><div><div class="eyebrow">INVENTORY</div><h1>Items</h1><p>Browse warehouse inventory and stock availability.</p></div></div><section class="panel"><form class="filter-bar" method="get"><label class="search-field"><span>⌕</span><input name="q" value="<?= e($search) ?>" placeholder="Search code, name or location"></label><select name="category"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?= e($c) ?>" <?= $category===$c?'selected':'' ?>><?= e($c) ?></option><?php endforeach;?></select><button class="button light">Filter</button><?php if($search||$category):?><a class="text-link" href="<?= e(url('user/items.php')) ?>">Clear</a><?php endif;?></form><div class="table-wrap"><table><thead><tr><th>Item code</th><th>Item name</th><th>Category</th><th>Location</th><th>Quantity</th><th>Unit</th><th>Reorder level</th><th>Actions</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="8" class="empty">No inventory items found.</td></tr><?php else:foreach($rows as $r):?><tr><td><b><?= e($r['item_code']) ?></b></td><td><?= e($r['item_name']) ?></td><td><?= e($r['category']) ?></td><td><?= e($r['location']) ?></td><td><?php if($r['quantity']<=$r['reorder_level']):?><span class="badge warning"><?= e($r['quantity']) ?></span><?php else:?><?= e($r['quantity']) ?><?php endif;?></td><td><?= e($r['unit']) ?></td><td><?= e($r['reorder_level']) ?></td><td><a class="text-link" href="<?= e(url('user/item-details.php?id='.$r['id'])) ?>">View details →</a></td></tr><?php endforeach;endif;?></tbody></table></div><div class="table-foot"><?= count($rows) ?> item<?= count($rows)===1?'':'s' ?></div></section><?php layoutEnd();?>
